// Shared profile menu: the dialog behind the profile icon on the Projects and Prompts pages.
// Both pages call RepoProfileMenu.install() so the icon opens the same sign-in / account menu.
(()=>{
const A=window.RepoAccount,$=s=>document.querySelector(s);
function escape(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
const googleMark='<svg class="google-mark" viewBox="0 0 24 24" width="22" height="22" aria-hidden="true"><path fill="#4285F4" d="M23 12.27c0-.8-.07-1.56-.2-2.3H12v4.35h6.17a5.27 5.27 0 0 1-2.29 3.46v2.87h3.7C21.74 18.65 23 15.7 23 12.27Z"/><path fill="#34A853" d="M12 23.5c3.1 0 5.7-1.03 7.6-2.8l-3.7-2.87c-1.03.69-2.35 1.1-3.9 1.1-3 0-5.54-2.02-6.45-4.74H1.74v2.97A11.5 11.5 0 0 0 12 23.5Z"/><path fill="#FBBC05" d="M5.55 14.19a6.9 6.9 0 0 1 0-4.38V6.84H1.74a11.5 11.5 0 0 0 0 10.32l3.81-2.97Z"/><path fill="#EA4335" d="M12 5.07c1.69 0 3.2.58 4.4 1.72l3.29-3.29C17.7 1.65 15.1.5 12 .5A11.5 11.5 0 0 0 1.74 6.84l3.81 2.97C6.46 7.09 9 5.07 12 5.07Z"/></svg>';
const githubMark='<svg class="github-mark" viewBox="0 0 24 24" width="24" height="24" fill="currentColor" aria-hidden="true"><path d="M12 .5C5.37.5 0 5.87 0 12.5c0 5.3 3.438 9.8 8.205 11.385.6.113.82-.258.82-.577 0-.285-.01-1.04-.015-2.04-3.338.725-4.043-1.61-4.043-1.61-.546-1.387-1.333-1.756-1.333-1.756-1.09-.745.083-.73.083-.73 1.205.085 1.838 1.237 1.838 1.237 1.07 1.835 2.807 1.305 3.492.998.108-.776.418-1.305.762-1.605-2.665-.305-5.467-1.333-5.467-5.93 0-1.31.467-2.38 1.235-3.22-.123-.303-.535-1.523.117-3.176 0 0 1.008-.323 3.3 1.23a11.52 11.52 0 0 1 3.003-.404c1.02.005 2.047.138 3.003.404 2.29-1.553 3.297-1.23 3.297-1.23.654 1.653.242 2.873.12 3.176.77.84 1.232 1.91 1.232 3.22 0 4.61-2.807 5.622-5.48 5.92.43.37.823 1.102.823 2.222 0 1.606-.015 2.896-.015 3.29 0 .322.216.694.825.576C20.565 22.297 24 17.8 24 12.5 24 5.87 18.627.5 12 .5Z"/></svg>';
const signinIcon=path=>`<svg width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${path}</svg>`;
function signinContent(){return `<p class="signin-intro">Sign in to keep your finds with you.</p><ul class="signin-benefits"><li><span class="signin-benefit-icon">${signinIcon('<rect x="3" y="4" width="18" height="16" rx="3"/><path d="m10 9 5 3-5 3Z"/>')}</span><div><strong>Pick up where you left off</strong><p>Choose to sync your viewing history across devices.</p></div></li><li><span class="signin-benefit-icon">${signinIcon('<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>')}</span><div><strong>Keep your favourites with you</strong><p>Save liked projects and find them on any device.</p></div></li><li><span class="signin-benefit-icon">${signinIcon('<circle cx="6" cy="5" r="2"/><circle cx="18" cy="5" r="2"/><circle cx="12" cy="19" r="2"/><path d="M6 7v3a6 6 0 0 0 6 6m6-9v3a6 6 0 0 1-6 6v1"/>')}</span><div><strong>Know what you’ve made your own</strong><p>Create forks on GitHub. Track your verified public forks across devices.</p></div></li><li><span class="signin-benefit-icon">${signinIcon('<path d="M8 3v4m8-4v4M6 7h12v4a6 6 0 0 1-6 6v4"/>')}</span><div><strong>Build with your AI assistant</strong><p>Create a personal key to use RepoShelf as a connector in Claude or Codex.</p></div></li></ul>${A.enabled?`<a class="button lime github-signin" href="/api/auth?action=start">${githubMark}<span>Sign in with GitHub</span><svg class="signin-arrow" viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6"/></svg></a>${A.googleEnabled?`<a class="button outline google-signin" href="/api/auth?action=start&provider=google">${googleMark}<span>Continue with Google</span></a><p class="signin-note">GitHub also unlocks forks, repository submissions and reports. Google works for likes, collections and history. Use the same option each time, or connect both in Account &amp; data to keep one collection.</p>`:''}<p class="signin-legal">By signing in you agree to our <a href="/terms.html" target="_blank" rel="noopener">Terms of Service</a> and acknowledge our <a href="/privacy.html" target="_blank" rel="noopener">Privacy Policy</a>. See our <a href="/cookies.html" target="_blank" rel="noopener">Cookie Policy</a> for how cookies and storage are used.</p><p class="signin-security">Sign-in is handled by ${A.googleEnabled?'GitHub or Google':'GitHub'}.<br>RepoShelf never sees your password.</p>`:'<p class="signin-security">GitHub sign-in is being configured. You can continue browsing the catalog.</p>'}`}

let options={};
function toast(message){if(options.toast)return options.toast(message);const t=$('#toast');if(t){t.textContent=message;t.classList.add('visible');setTimeout(()=>t.classList.remove('visible'),4000)}}
function render(){const person=A.user,collectionLink=options.collectionHref||'';$('#account').dataset.mode=person?'account':'signin';$('#account-mode-label').textContent=person?'Your account':'Sign-In';$('#account-title').textContent=person?'Your profile':'Your next project starts here.';$('#account-title').classList.toggle('sr-only',Boolean(person));
const icon=kind=>signinIcon({link:'<path d="M10 14a4 4 0 0 0 5.7 0l3-3a4 4 0 0 0-5.7-5.7l-1 1M14 10a4 4 0 0 0-5.7 0l-3 3A4 4 0 0 0 11 18.7l1-1"/>',connector:'<path d="M8 3v4m8-4v4M6 7h12v4a6 6 0 0 1-6 6v4M9 7v4m6-4v4"/>',collection:'<path d="M6 3h12v18l-6-4-6 4Z"/>',submissions:'<rect x="4" y="4" width="16" height="16" rx="3"/><path d="M8 12h8m-4-4v8"/>',promotions:'<path d="m3 10 15-5v14L3 14Zm15-5 3-2v18l-3-2M6 15l2 6h4l-2-5"/>',privacy:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 12 3 3 5-6"/>',admin:'<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="9" cy="6" r="2"/><circle cx="15" cy="12" r="2"/><circle cx="9" cy="18" r="2"/>',signout:'<path d="M9 4H4v16h5m4-4 4-4-4-4m-5 4h13"/>'}[kind]);
const row=(kind,label,attrs,badge='')=>`<${attrs.startsWith('href')?'a':'button'} class="profile-link" ${attrs}><span class="profile-link-icon">${icon(kind)}</span><span>${label}</span>${badge?'<small class="profile-test">'+badge+'</small>':''}<span class="profile-chevron" aria-hidden="true">›</span></${attrs.startsWith('href')?'a':'button'}>`;
$('#account-auth').innerHTML=person?`<div class="profile-identity"><span class="profile-avatar"><span>${escape(person.name.slice(0,1).toUpperCase())}</span>${/^https:\/\/avatars\.githubusercontent\.com\/u\/\d+\?s=96$/.test(person.avatarUrl||'')?`<img src="${escape(person.avatarUrl)}" alt="" referrerpolicy="no-referrer">`:''}</span><div><strong>${person.githubConnected?'@':''}${escape(person.name)}</strong><p>${person.githubConnected?'Signed in with GitHub':'Signed in with Google'}</p></div></div>${person.admin?'<span class="profile-role">Administrator</span>':''}<nav class="profile-navigation" aria-label="Profile"><section class="profile-group" aria-labelledby="profile-projects"><h3 id="profile-projects">Your projects</h3>${row('collection','My Collection',collectionLink?`href="${collectionLink}"`:'type="button" id="profile-collection"')}${row('submissions','My submissions','href="/submissions.html"')}</section><section class="profile-group" aria-labelledby="profile-preferences"><h3 id="profile-preferences">Account</h3>${row('privacy','Account & data','href="/account.html"')}${row('link','Linked accounts','href="/account.html#signin-methods"')}${row('connector','Connect your AI assistant','href="/connect.html"')}${row('signout','Sign out','type="button" id="signout"')}</section>${person.admin?`<section class="profile-group" aria-labelledby="profile-administration"><h3 id="profile-administration">Administration</h3>${row('admin','Admin dashboard','href="/admin.html"')}${row('promotions','My promotions','href="/promotions.html"','Test')}</section>`:''}</nav>`:signinContent();const avatar=$('.profile-avatar img');if(avatar)avatar.onerror=()=>avatar.remove();if($('#profile-collection'))$('#profile-collection').onclick=()=>{$('#account').close();options.openCollection&&options.openCollection()};if($('#signout'))$('#signout').onclick=async()=>{try{await A.signout();toast('Signed out. Your saved account collection is safe.')}catch(e){toast(e.message)}}}
function updateButton(){const button=$('#account-button');if(!button)return;const label=A.user?`Account menu for ${A.user.githubConnected?'@':''}${A.user.name}`:'Sign in';button.classList.toggle('signed-in',Boolean(A.user));button.setAttribute('aria-label',label);button.title=label}
function open(){render();if(!$('#account').open)$('#account').showModal()}
function install(opts={}){options=opts;const dialog=$('#account'),button=$('#account-button');if(!dialog||!button)return;button.onclick=open;dialog.querySelectorAll('.close').forEach(b=>b.onclick=()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});window.addEventListener('reposhelf-account',()=>{updateButton();if(dialog.open)render()});updateButton()}
window.RepoProfileMenu={install,open,render,updateButton};
})();
